import java.util.*;

public class Solution {
    // Kosaraju: ordem de término no grafo; DFS no transposto em ordem decrescente de término.
    static int[] componentes(int n, int[][] arestas) {
        int[][] g = adj(n, arestas, false), gt = adj(n, arestas, true);
        int[] ordem = new int[n];
        int tam = 0;
        boolean[] visto = new boolean[n];
        int[] it = new int[n];
        int[] pilha = new int[n];
        for (int s = 0; s < n; s++) {
            if (visto[s]) continue;
            int topo = 0;
            pilha[topo++] = s;
            visto[s] = true;
            while (topo > 0) {
                int u = pilha[topo - 1];
                if (it[u] < g[u].length) {
                    int v = g[u][it[u]++];
                    if (!visto[v]) {
                        visto[v] = true;
                        pilha[topo++] = v;
                    }
                } else {
                    ordem[tam++] = u; // terminou
                    topo--;
                }
            }
        }
        int[] comp = new int[n];
        Arrays.fill(comp, -1);
        int c = 0;
        for (int i = n - 1; i >= 0; i--) {
            int s = ordem[i];
            if (comp[s] != -1) continue;
            int topo = 0;
            pilha[topo++] = s;
            comp[s] = c;
            while (topo > 0) {
                int u = pilha[--topo];
                for (int v : gt[u]) if (comp[v] == -1) { comp[v] = c; pilha[topo++] = v; }
            }
            c++;
        }
        return comp;
    }

    static int arestasCondensadas(int n, int[][] arestas) {
        int[] comp = componentes(n, arestas);
        Set<Long> vistas = new HashSet<>();
        for (int[] e : arestas) {
            int a = comp[e[0]], b = comp[e[1]];
            if (a != b) vistas.add((long) a * n + b);
        }
        return vistas.size();
    }

    private static int[][] adj(int n, int[][] arestas, boolean transposto) {
        int[] grau = new int[n];
        for (int[] e : arestas) grau[transposto ? e[1] : e[0]]++;
        int[][] g = new int[n][];
        for (int i = 0; i < n; i++) g[i] = new int[grau[i]];
        for (int[] e : arestas) {
            int u = transposto ? e[1] : e[0], v = transposto ? e[0] : e[1];
            g[u][--grau[u]] = v;
        }
        return g;
    }
}

