import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static void mesmaParticao(int[][] esperado, int[] comp) {
        Set<Integer> ids = new HashSet<>();
        for (int[] grupo : esperado) {
            for (int v : grupo) assertEquals(comp[grupo[0]], comp[v], "vértice " + v);
            assertTrue(ids.add(comp[grupo[0]]), "dois grupos com o mesmo id");
        }
    }

    @Test void exemploClassico() {
        int[][] e = {{0, 1}, {1, 2}, {2, 0}, {2, 3}, {3, 4}, {4, 5}, {5, 3}, {6, 5}, {6, 7}};
        mesmaParticao(new int[][]{{0, 1, 2}, {3, 4, 5}, {6}, {7}}, Solution.componentes(8, e));
        assertEquals(3, Solution.arestasCondensadas(8, e));
    }

    @Test void arestasRepetidasELacos() {
        int[][] e = {{0, 1}, {1, 0}, {0, 2}, {1, 2}, {2, 2}};
        mesmaParticao(new int[][]{{0, 1}, {2}}, Solution.componentes(3, e));
        assertEquals(1, Solution.arestasCondensadas(3, e));
    }

    @Test void cicloGiganteSemEstouro() {
        int n = 200_000;
        int[][] e = new int[n][];
        for (int i = 0; i < n; i++) e[i] = new int[]{i, (i + 1) % n};
        int[] comp = Solution.componentes(n, e);
        for (int v : comp) assertEquals(comp[0], v);
    }

    @Test void cadeiaGigante() {
        int n = 200_000;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{i, i + 1};
        assertEquals(n - 1, Solution.arestasCondensadas(n, e));
    }
}
